$ErrorActionPreference='Stop'
$repo='F:/JericoEngine/JericoEngine';$base=Join-Path $repo 'build/n0-validation/local-packages/png-rev1-validation';$freezePath=Join-Path $repo 'build/n0-validation/local-packages/png-audit/source-freeze-png-candidate.json';$argsPath=Join-Path $repo 'build/n0-validation/local-packages/png-audit/validation-arguments.json'
$freezeExpected='4DB39EDF21D605D64DA4F6E85CD9613B4023EC3C4687CB3AB02E358178FEB838';$argsExpected='6A873AD384A1E755D1F69D60649709E377DA0105E967EB9F22BD74D66EA4F5E1'
if((Get-FileHash $freezePath -Algorithm SHA256).Hash -ne $freezeExpected){throw 'PNG freeze manifest hash mismatch'};if((Get-FileHash $argsPath -Algorithm SHA256).Hash -ne $argsExpected){throw 'PNG args manifest hash mismatch'}
$freeze=Get-Content -Raw $freezePath|ConvertFrom-Json;$before=@();foreach($e in $freeze.entries){$p=[string]$e.path;$h=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToUpperInvariant();if($h -ne [string]$e.sha256){throw "PNG frozen input mismatch: $p"};$before += [ordered]@{path=$p;bytes=(Get-Item $p).Length;sha256=$h}}
if($before.Count -ne 514){throw "Expected 514 inputs, found $($before.Count)"}
$manifest=Get-Content -Raw $argsPath|ConvertFrom-Json;$vector=[string[]]$manifest.producer.argv;$output=[string]$manifest.producer.outputMustBeAbsent;$cmake=[string]$manifest.producer.executable;$script="$repo/cmake/Tools/LocalPackages/PNG/BuildPngPackage.cmake"
if($vector.Count -ne 5 -or $vector[3] -ne '-P' -or $vector[4] -ne $script){throw 'PNG producer vector count/mode/script guard failed'};if(Test-Path $output){throw 'PNG output exists; refusing overwrite'}
[IO.File]::WriteAllText((Join-Path $base 'png-producer-argv.json'),(@{executable=$cmake;workingDirectory=$base;arguments=$vector}|ConvertTo-Json -Depth 4),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $base 'png-inputs-before.json'),(@{freezeSHA256=$freezeExpected;argsSHA256=$argsExpected;inputCount=$before.Count;inputs=$before}|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
$psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName=$cmake;$psi.WorkingDirectory=$base;$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;foreach($a in $vector){[void]$psi.ArgumentList.Add($a)}
$proc=[Diagnostics.Process]::new();$proc.StartInfo=$psi;$sw=[Diagnostics.Stopwatch]::StartNew();if(-not $proc.Start()){throw 'PNG CMake process failed to start'};$ot=$proc.StandardOutput.ReadToEndAsync();$et=$proc.StandardError.ReadToEndAsync();$proc.WaitForExit();$exit=$proc.ExitCode;$cpu=$proc.TotalProcessorTime.TotalSeconds;try{$peak=$proc.PeakWorkingSet64}catch{$peak=$null};$sw.Stop();$out=$ot.GetAwaiter().GetResult();$err=$et.GetAwaiter().GetResult()
[IO.File]::WriteAllText((Join-Path $base 'png-producer.stdout.log'),$out,[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $base 'png-producer.stderr.log'),$err,[Text.UTF8Encoding]::new($false))
$after=@();foreach($e in $freeze.entries){$p=[string]$e.path;$h=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToUpperInvariant();$after += [ordered]@{path=$p;sha256=$h;matchesFreeze=($h -eq [string]$e.sha256)}}
[IO.File]::WriteAllText((Join-Path $base 'png-inputs-after-producer.json'),(@{inputCount=$after.Count;allMatch=(@($after|Where-Object{!$_.matchesFreeze}).Count -eq 0);inputs=$after}|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
$r=[ordered]@{exitCode=$exit;elapsedSeconds=[Math]::Round($sw.Elapsed.TotalSeconds,3);cpuSeconds=[Math]::Round($cpu,3);peakWorkingSetBytes=$peak;memoryScope='cmake.exe parent only; not child MSBuild/cl/link';stdoutBytes=[Text.Encoding]::UTF8.GetByteCount($out);stderrBytes=[Text.Encoding]::UTF8.GetByteCount($err);outputExists=(Test-Path $output);frozenInputs=$after.Count;frozenMatch=(@($after|Where-Object{!$_.matchesFreeze}).Count -eq 0)};[IO.File]::WriteAllText((Join-Path $base 'png-producer-result.json'),($r|ConvertTo-Json -Depth 4),[Text.UTF8Encoding]::new($false));Write-Output ($r|ConvertTo-Json -Compress)
